export function getEmissorByCnpj(cnpj: string): Emissor | undefined {
  return emissores.find(e => e.cnpj === cnpj);
}

export function getEmissorByIsin(isin: string): Emissor | undefined {
  const emissao = emissoes.find(e => e.isin === isin);
  if (!emissao || !emissao.cnpjEmissor) return undefined;
  return getEmissorByCnpj(emissao.cnpjEmissor);
}
